/**
 * Demo tenant: 24 months of activity data.
 *
 * 16 monthly activity streams x 24 months (Jan 2023 – Dec 2024) = 384 entries,
 * covering all four Scope 1 source types, Scope 2 location *and* market based, and
 * six Scope 3 categories.
 *
 * Quantities are generated by a closed-form seasonal function rather than a random
 * generator, so the dataset is byte-identical on every run, in every environment
 * and in the seeded database:
 *
 *     quantity(year, month) = base x yearFactor(year) x (1 + amplitude x cos(2π(month-1)/12))
 *
 * A positive amplitude peaks in January (heating, boilers), a negative one peaks in
 * July (cooling, refrigerant leakage). `yearFactor` falls 4.5 % in 2024, so the
 * dataset shows a real year-on-year reduction for the trend and target views.
 */

import type {
  CalculationApproach,
  DataQualityLevel,
  DataSourceType,
  GHGScope,
  Scope3Category,
} from "@/lib/core/enums";
import { roundTo } from "@/lib/core/number";
import type { ReportingPeriod } from "@/lib/core/period";
import type { CalculationEntry, Scope1SourceType } from "@/lib/domain/emissions/orchestrator";
import type { ContractualInstrument } from "@/lib/domain/emissions/scope2";
import type { MeasurementType } from "@/lib/domain/quality/score";

import { FACTOR_SECTORS, REGION_APAC, REGION_GLOBAL } from "./emission-factors";
import { DEMO_ORGANIZATION_ID, DEMO_SOURCE_HIERARCHY } from "./organization";

/** Reporting years covered by the fixture, oldest first. */
