export const DEMO_CURRENT_YEAR = 2024;
export const DEMO_MONTHS_PER_YEAR = 12;
/** 16 streams x 24 months. */
export const DEMO_EXPECTED_ENTRY_COUNT = 384;

/** Activity volume index per reporting year. */
const YEAR_FACTOR: Readonly<Record<number, number>> = {
  2023: 1,
  2024: 0.955,
};

type StreamSpec = {
  readonly key: string;
  readonly emissionSourceId: string;
  readonly label: string;
  readonly scope: GHGScope;
  readonly scope3Category: Scope3Category | null;
  readonly scope1SourceType?: Scope1SourceType;
  readonly approach: CalculationApproach;
  readonly unit: string;
  /** Monthly quantity at the seasonal mean, in `unit`. */
  readonly base: number;
  /** Seasonal amplitude; positive peaks in January, negative in July. */
  readonly amplitude: number;
  readonly decimals: number;
  readonly region: string;
  readonly country: string | null;
  readonly sector: string | null;
  readonly gasTypes?: readonly string[];
  readonly mobileMethod?: "FUEL" | "DISTANCE";
  readonly supplierId?: string;
  readonly measurementType: MeasurementType;
  readonly dataSource: DataSourceType;
  readonly dataQuality: DataQualityLevel;
  readonly isEstimated: boolean;
  readonly hasEvidence: boolean;
  readonly activityDataUncertainty: number;
  readonly methodologyUncertainty: number;
  /** Master-data foreign keys carried by the persisted `ActivityDataEntry`. */
  readonly refs: Readonly<Record<string, string>>;
  /** Contractual instruments, for the market-based Scope 2 streams. */
  readonly instruments?: readonly ContractualInstrument[];
  /** Refrigerant balance, for the fugitive stream. */
  readonly fugitiveBase?: {
    readonly gas?: string;
    readonly blend?: string;
    readonly inventoryChangeShare: number;
    readonly disposalShare: number;
  };
};

