/** Streams, exported so the seed and the UI can enumerate them. */
export const DEMO_ACTIVITY_STREAMS = STREAMS;

// ---------------------------------------------------------------------------
// Generation
// ---------------------------------------------------------------------------

function monthPeriod(year: number, month: number): ReportingPeriod {
  return {
    start: new Date(Date.UTC(year, month - 1, 1)),
    // Last instant of the month, expressed as the last day at 00:00 UTC.
    end: new Date(Date.UTC(year, month, 0)),
  };
}

function seasonalQuantity(spec: StreamSpec, year: number, month: number): number {
  const seasonal = 1 + spec.amplitude * Math.cos((2 * Math.PI * (month - 1)) / 12);
  return roundTo(spec.base * (YEAR_FACTOR[year] ?? 1) * seasonal, spec.decimals);
}

/** `ActivityData` header rows: one per stream per reporting year. */
export type DemoActivityData = {
  readonly id: string;
  readonly organizationId: string;
  readonly facilityId: string | null;
  readonly businessUnitId: string | null;
  readonly name: string;
  readonly description: string;
  readonly scope: GHGScope;
  readonly scope3Category: Scope3Category | null;
  readonly reportingYear: number;
  readonly reportingMonth: null;
  readonly dataSource: DataSourceType;
  readonly dataQuality: DataQualityLevel;
  readonly isVerified: boolean;
};

/** `ActivityDataEntry` rows, shaped for persistence. */
export type DemoActivityDataEntry = {
  readonly id: string;
  readonly activityDataId: string;
  readonly emissionSourceId: string;
  readonly quantity: number;
  readonly unit: string;
  readonly startDate: Date;
  readonly endDate: Date;
  readonly notes: string;
  readonly evidenceUrl: string | null;
  readonly isEstimated: boolean;
  /** Relative uncertainty as a 0..1 fraction, matching the Prisma column. */
  readonly uncertainty: number;
  readonly productId: string | null;
  readonly supplierId: string | null;
  readonly vehicleId: string | null;
  readonly fuelId: string | null;
  readonly refrigerantId: string | null;
  readonly rawMaterialId: string | null;
  readonly logisticsRouteId: string | null;
  readonly energySourceId: string | null;
  readonly wasteTypeId: string | null;
  readonly waterSourceId: string | null;
};

function activityDataId(spec: StreamSpec, year: number): string {
  return `demo-ad-${spec.key}-${year}`;
}

function entryId(spec: StreamSpec, year: number, month: number): string {
  return `demo-ade-${spec.key}-${year}-${String(month).padStart(2, "0")}`;
}

function buildActivityData(): readonly DemoActivityData[] {
  const rows: DemoActivityData[] = [];
  for (const spec of STREAMS) {
    const hierarchy = DEMO_SOURCE_HIERARCHY[spec.emissionSourceId];
    for (const year of DEMO_REPORTING_YEARS) {
      rows.push({
        id: activityDataId(spec, year),
        organizationId: DEMO_ORGANIZATION_ID,
        facilityId: hierarchy.facilityId,
        businessUnitId: hierarchy.businessUnitId,
        name: `${spec.label} ${year}`,
        description: `Monthly ${spec.unit} readings for ${year}.`,
        scope: spec.scope,
        scope3Category: spec.scope3Category,
        reportingYear: year,
        reportingMonth: null,
        dataSource: spec.dataSource,
        dataQuality: spec.dataQuality,
        // The prior year has completed its assurance cycle.
        isVerified: year === DEMO_BASELINE_YEAR,
      });
    }
  }
  return rows;
}

function buildEntries(): readonly DemoActivityDataEntry[] {
  const rows: DemoActivityDataEntry[] = [];
  for (const spec of STREAMS) {
    for (const year of DEMO_REPORTING_YEARS) {
      for (let month = 1; month <= DEMO_MONTHS_PER_YEAR; month += 1) {
        const period = monthPeriod(year, month);
        rows.push({
          id: entryId(spec, year, month),
          activityDataId: activityDataId(spec, year),
          emissionSourceId: spec.emissionSourceId,
          quantity: seasonalQuantity(spec, year, month),
          unit: spec.unit,
          startDate: period.start,
          endDate: period.end,
          notes: `${spec.label} — ${year}-${String(month).padStart(2, "0")}`,
          evidenceUrl: spec.hasEvidence
            ? `https://example.com/hanbit-materials/evidence/${spec.key}/${year}-${String(month).padStart(2, "0")}.pdf`
            : null,
          isEstimated: spec.isEstimated,
          uncertainty: roundTo(spec.activityDataUncertainty / 100, 4),
          productId: spec.refs.productId ?? null,
          supplierId: spec.refs.supplierId ?? null,
          vehicleId: spec.refs.vehicleId ?? null,
          fuelId: spec.refs.fuelId ?? null,
          refrigerantId: spec.refs.refrigerantId ?? null,
          rawMaterialId: spec.refs.rawMaterialId ?? null,
          logisticsRouteId: spec.refs.logisticsRouteId ?? null,
          energySourceId: spec.refs.energySourceId ?? null,
          wasteTypeId: spec.refs.wasteTypeId ?? null,
          waterSourceId: spec.refs.waterSourceId ?? null,
        });
      }
    }
  }
  return rows;
}

export const DEMO_ACTIVITY_DATA: readonly DemoActivityData[] = buildActivityData();
export const DEMO_ACTIVITY_ENTRIES: readonly DemoActivityDataEntry[] = buildEntries();

// ---------------------------------------------------------------------------
// Projection onto the orchestrator input
// ---------------------------------------------------------------------------

const STREAM_BY_ENTRY_ID: ReadonlyMap<string, StreamSpec> = new Map(
  STREAMS.flatMap((spec) =>
    DEMO_REPORTING_YEARS.flatMap((year) =>
      Array.from({ length: DEMO_MONTHS_PER_YEAR }, (_, index) => {
        const month = index + 1;
        return [entryId(spec, year, month), spec] as const;
      }),
    ),
  ),
);

/**
 * Projects a persisted entry onto the `CalculationEntry` the orchestrator takes.
 * The hierarchy ids are denormalised here — exactly the join the data layer does
 * for real database rows.
 */
export function toCalculationEntry(entry: DemoActivityDataEntry): CalculationEntry {
  const spec = STREAM_BY_ENTRY_ID.get(entry.id);
  if (!spec) {
    throw new Error(`No demo activity stream registered for entry ${entry.id}`);
  }
  const hierarchy = DEMO_SOURCE_HIERARCHY[spec.emissionSourceId];

  return {
    id: entry.id,
    name: entry.notes,
    quantity: entry.quantity,
    unit: entry.unit,
    dataPeriod: { start: entry.startDate, end: entry.endDate },
    scope: spec.scope,
    scope3Category: spec.scope3Category,
    scope1SourceType: spec.scope1SourceType,
    approach: spec.approach,
    region: spec.region,
    country: spec.country,
    sector: spec.sector,
    supplierId: spec.supplierId ?? null,
    gasTypes: spec.gasTypes,
    businessUnitId: hierarchy.businessUnitId,
    facilityId: hierarchy.facilityId,
    buildingId: hierarchy.buildingId,
    productionLineId: hierarchy.productionLineId,
    equipmentId: hierarchy.equipmentId,
    emissionSourceId: hierarchy.emissionSourceId,
    mobileMethod: spec.mobileMethod,
    fugitive: spec.fugitiveBase
      ? {
          method: "SCREENING",
          blend: spec.fugitiveBase.blend,
          gas: spec.fugitiveBase.gas as never,
          inventoryChange: roundTo(entry.quantity * spec.fugitiveBase.inventoryChangeShare, 3),
          purchases: entry.quantity,
          disposals: roundTo(entry.quantity * spec.fugitiveBase.disposalShare, 3),
        }
      : undefined,
    market: spec.instruments ? { instruments: spec.instruments } : undefined,
    measurementType: spec.measurementType,
    isEstimated: spec.isEstimated,
    hasEvidence: spec.hasEvidence,
    unitConsistent: true,
    sourceConsistentWithPriorPeriod: true,
    methodConsistentWithPriorPeriod: true,
    activityDataUncertainty: spec.activityDataUncertainty,
    methodologyUncertainty: spec.methodologyUncertainty,
  };
}

/** Every fixture entry, projected for the orchestrator. */
export const DEMO_CALCULATION_ENTRIES: readonly CalculationEntry[] =
  DEMO_ACTIVITY_ENTRIES.map(toCalculationEntry);

/** Entries whose data period falls inside the requested reporting year. */
export function demoEntriesForYear(year: number): readonly CalculationEntry[] {
  return DEMO_CALCULATION_ENTRIES.filter(
    (entry) => entry.dataPeriod?.start.getUTCFullYear() === year,
  );
}

/** Full-year reporting period for a calendar reporting year. */
export function demoPeriodForYear(year: number): ReportingPeriod {
  return {
    start: new Date(Date.UTC(year, 0, 1)),
    end: new Date(Date.UTC(year, 11, 31)),
  };
}

/** Total activity quantity per unit, used by the seed-parity test. */
export function demoActivityTotals(): Readonly<Record<string, number>> {
  const totals: Record<string, number> = {};
  for (const entry of DEMO_ACTIVITY_ENTRIES) {
    const key = `${entry.emissionSourceId}:${entry.unit}`;
    totals[key] = roundTo((totals[key] ?? 0) + entry.quantity, 4);
  }
  return totals;
}
